class FilterOperatorError(Exception):
    def __init__(self, expression):
        self.expression = expression

    def __str__(self):
        return "Unsupported operator in the expression:{}".format(self.expression)


class DuplicatedFieldError(Exception):
    def __init__(self, field, msg):
        self.field = field
        self.msg = msg

    def __str__(self):
        return "Duplicated field:{}.\n{}".format(self.field, self.msg)


class FileNotExist(Exception):
    pass
